n, k, m = map(int, input().split())

a = []
for _ in range(n):
    a.append([int(x) for x in input().split()])

b = []
for _ in range(k):
    b.append([int(x) for x in input().split()])

# Each row must be a separate list, so no [[0] * m] * n here
c = [[0] * m for _ in range(n)]

for i in range(n):
    for j in range(m):
        total = 0
        for t in range(k):
            total += a[i][t] * b[t][j]
        c[i][j] = total

for row in c:
    print(" ".join(str(x) for x in row))

n = int(input())

triangle = []

for r in range(n):
    row = [1] * (r + 1)
    for j in range(1, r):
        row[j] = triangle[r - 1][j - 1] + triangle[r - 1][j]
    triangle.append(row)

for row in triangle:
    print(" ".join(str(x) for x in row))

words = input().split()

first = words[0]
prefix_length = len(first)

for i in range(len(first)):
    ch = first[i]
    mismatch = False
    for word in words[1:]:
        if i >= len(word) or word[i] != ch:
            mismatch = True
            break
    if mismatch:
        prefix_length = i
        break

prefix = first[:prefix_length]

if prefix == "":
    print("NONE")
else:
    print(prefix)

n = int(input())

grid = [[0] * n for _ in range(n)]
num = 1
top, bottom = 0, n - 1
left, right = 0, n - 1

while top <= bottom and left <= right:
    for j in range(left, right + 1):
        grid[top][j] = num
        num += 1
    top += 1

    for i in range(top, bottom + 1):
        grid[i][right] = num
        num += 1
    right -= 1

    if top <= bottom:
        for j in range(right, left - 1, -1):
            grid[bottom][j] = num
            num += 1
        bottom -= 1

    if left <= right:
        for i in range(bottom, top - 1, -1):
            grid[i][left] = num
            num += 1
        left += 1

for row in grid:
    print(" ".join(str(x) for x in row))
